/// Folds a remote catalog into the per-endpoint fetch result.
///
/// Without a [mediaSlot] the merge is chat-only: the catalog's
/// `contextWindows` fill gaps the endpoint didn't report, the chat id
/// list stays exactly as the endpoint reported it (the catalog never
/// seeds chat ids — `/v1/models` is the source of truth).
///
/// With [mediaSlot] the merge flips to media-only: the chat id list
/// from the endpoint is DISCARDED (chat ids like `MiniMax-M3` are
/// useless in the image picker), and the merged id list contains
/// exactly the catalog's per-slot media ids. The catalog is the only

/// exactly the catalog's per-slot media ids. The catalog is the only
/// source of media ids for providers whose chat endpoint never
/// publishes them.
ModelsEndpointInfo mergeWithRemoteCatalog({
  required ModelsEndpointInfo endpointInfo,
  required String? providerKind,
  required RemoteModelsCatalog? catalog,
  List<String> mediaSlot = const [],
}) {
  if (catalog == null) return endpointInfo;
  final entry = catalog.providers[providerKind ?? ''];
  if (entry == null) return endpointInfo;
  final (_, windows, maxTokens) = endpointInfo;
  final List<String> mergedIds;
  if (mediaSlot.isEmpty) {
    // Chat path: keep the endpoint's id list verbatim, the catalog
    // never augments chat ids.
    mergedIds = <String>[...endpointInfo.$1];
  } else {
    // Media path: drop the chat list, answer exactly the catalog's
    // per-slot media ids. Picker sees only the right model kind.
    mergedIds = <String>[];
    for (final slot in mediaSlot) {
      final seed = entry.media[slot];
      if (seed == null) continue;
      for (final id in seed) {
        if (!mergedIds.contains(id)) mergedIds.add(id);
      }
    }
  }
  final mergedWindows = <String, int>{
    ...entry.contextWindows,
    ...windows, // endpoint reported limits override catalog defaults
  };
  final mergedMaxTokens = <String, int>{...maxTokens};
  return (mergedIds, mergedWindows, mergedMaxTokens);
}

/// The media-model list the picker shows for the slot when no override
/// is configured. Empty when the catalog doesn't list the slot — the
/// picker falls through to manual entry, the existing behaviour.
List<String> remoteMediaModelsFor({
  required String? providerKind,
  required String slot,
  required RemoteModelsCatalog? catalog,
}) {
  if (catalog == null) return const [];
  final entry = catalog.providers[providerKind ?? ''];
  if (entry == null) return const [];
  return entry.media[slot] ?? const [];
}

/// Chat model ids the catalog knows about for [providerKind] — used
/// only as a LAST-RESORT picker fallback when the live `/v1/models`
/// fetch returns an empty list (e.g. token failure, 5xx, endpoint down).
/// The endpoint is ALWAYS the source of truth; this list just keeps the
/// picker from collapsing to the saved entry's single modelId when the
/// endpoint can't answer. The catalog ships these ids explicitly in
/// `contextWindows` so the data is data-driven, not hardcoded.
List<String> remoteChatModelsFor({
  required String? providerKind,
  required RemoteModelsCatalog? catalog,
}) {
  if (catalog == null) return const [];
  final entry = catalog.providers[providerKind ?? ''];
  if (entry == null) return const [];
  // Insertion order matches the catalog author intent (newest first).
  return [for (final key in entry.contextWindows.keys) key];
}

final class RemoteCatalogEnrichment {
  RemoteModelsCatalog? _cached;

  /// Returns the live parsed catalog (or null when no preload ran).
  RemoteModelsCatalog? get cached => _cached;

  /// Loads the catalog via [fetchRemoteModelsCatalog]. Failures (any
  /// network, timeout, or parse error) leave [_cached] untouched so a
  /// later preload can recover without surfacing prior failures.
  Future<void> preload({Uri? url, http.Client? client}) async {
    final loaded = await fetchRemoteModelsCatalog(url: url, client: client);
    if (loaded != null) {
      _cached = loaded;
      return;
    }
    // Network unavailable / 404 / timeout — seed the bundled fallback so
    // pickers still get catalog metadata + the data-driven chat id
    // fallback chain. The remote URL remains the source of truth when
    // it answers.
    _cached ??= bundledRemoteModelsCatalog;
  }

  /// Merges the cached catalog into [info] for [providerKind]. Used by
  /// hosts that want the merged view directly (pickers, settings flows)
  /// rather than going through the dispatcher twice.
  ///
  /// [mediaSlot] opts into seeding catalog media ids into the merged
  /// list — chat slots leave it empty, media pickers pass the slot name
  /// so the empty endpoint result gets the catalog defaults.
  ModelsEndpointInfo mergeFor(
    ModelsEndpointInfo info,
    String? providerKind, {
    List<String> mediaSlot = const [],
  }) {
    return mergeWithRemoteCatalog(
      endpointInfo: info,
      providerKind: providerKind,
      catalog: _cached,
      mediaSlot: mediaSlot,
    );
  }

  /// Media-model ids the catalog lists for [providerKind]/[slot], or an
  /// empty list when the catalog has no opinion.
  List<String> mediaFor(String? providerKind, String slot) {
    return remoteMediaModelsFor(
      providerKind: providerKind,
      slot: slot,
      catalog: _cached,
    );
  }

  /// Flat per-Mtok pricing the catalog lists for [providerKind]/[modelId],
  /// or null when the catalog ships no number — the picker renders `—`
  /// (never 0.00) on a miss (issue #278 E3).
  RemoteModelPricing? pricingFor(String? providerKind, String modelId) {
    final entry = _cached?.providers[providerKind ?? ''];
    return entry?.pricing[modelId];
  }

  /// Chat model ids the catalog knows about for [providerKind] — the
  /// LAST-RESORT fallback the picker uses when the live `/v1/models`
  /// fetch is empty. Endpoint-reported ids always win; this list is
  /// only consulted on the empty-result branch so the picker stays
  /// useful when the endpoint can't answer.
  List<String> chatFallbackFor(String? providerKind) {
    return remoteChatModelsFor(providerKind: providerKind, catalog: _cached);
  }
}

/// Process-wide [RemoteCatalogEnrichment] singleton. Hosts preload once
/// at boot and the rest of the code reads from this instance. Tests swap
/// it via [setRemoteCatalogEnrichmentForTesting].
RemoteCatalogEnrichment remoteCatalogEnrichment = RemoteCatalogEnrichment();

/// Test seam — swap in a fake enrichment so unit tests don't need a
/// real HTTP client. Not part of the public API.
@visibleForTesting
void setRemoteCatalogEnrichmentForTesting(RemoteCatalogEnrichment fake) {
  remoteCatalogEnrichment = fake;
}

